import glob
import zipfile
from taf.analyzer.pmcounter import PMCounterLogReader, PMNiddMapper
from taf.collectors.core import Factory

from .pmtocsv_converter import PmToCsvConverterObject


class PmToCsvConverterFactory(Factory):

    def create(self, configuration, existing_arguments):
        """
        Create a converter to convert PM files from XML to CSV format.

        :param configuration: Configuration information of converters
        :param existing_arguments: existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        :return: PmToCsvConverterObject
        """
        resulting_arguments = {}
        self._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        return PmToCsvConverterObject(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        """
        Builds the arguments for the constructor call

        :param configuration: Configuration information of converters
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        :param dict resulting_arguments:
            resulting arguments for the final constructor call
            (dict with constructor parameter name as key and argument value as value)
        """
        super(PmToCsvConverterFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        file_path_pattern = configuration.get("file_path_pattern")

        file_obj_iterator = (
            open(file_name, "rb")
            for file_name in glob.glob(file_path_pattern))

        resulting_arguments["pm_counter_log_reader"] = PMCounterLogReader(file_obj_iterator=file_obj_iterator)
        if "delimiter" in configuration:
            resulting_arguments["delimiter"] = configuration["delimiter"]
        if "output_file_name" in configuration:
            resulting_arguments["output_file_name"] = configuration["output_file_name"]
        if "nidd_path" in configuration:
            if ".zip" in configuration["nidd_path"]:
                with zipfile.ZipFile(configuration["nidd_path"]) as zip_file:
                    resulting_arguments["nidd_mapper"] = PMNiddMapper.from_file(zip_file.namelist()[0])
            else:
                resulting_arguments["nidd_mapper"] = PMNiddMapper.from_path(configuration["nidd_path"])
        else:
            resulting_arguments["nidd_mapper"] = PMNiddMapper.create_null_mapper()
